"""Tests of the robot description generated by xacro."""

import math
import xml.etree.ElementTree as ET
from pathlib import Path
from xml.dom.minidom import Node

import pytest
import xacro

URDF = Path(__file__).resolve().parents[1] / "urdf" / "minipock.urdf.xacro"
NAMESPACE = "minipock_0"
MODES = ("differential", "holonomic")
WHEEL_SEPARATION = 0.328
WHEEL_RADIUS = 0.0355


def _convert(node: Node) -> ET.Element:
    """Convert a minidom element, as returned by xacro, into an ElementTree element."""
    element = ET.Element(node.tagName, dict(node.attributes.items()))
    text = "".join(c.data for c in node.childNodes if c.nodeType == Node.TEXT_NODE).strip()
    element.text = text or None
    for child in node.childNodes:
        if child.nodeType == Node.ELEMENT_NODE:
            element.append(_convert(child))
    return element


def _robot(mode: str) -> ET.Element:
    """Process the source file with xacro and return the resulting URDF."""
    document = xacro.process_file(str(URDF), mappings={"namespace": f"{NAMESPACE}/", "mode": mode})
    return _convert(document.documentElement)


def _xyz_rpy(element: ET.Element | None) -> tuple[list[float], list[float]]:
    """Return the xyz and rpy of an `origin` element (zeros when absent)."""
    if element is None:
        return [0.0] * 3, [0.0] * 3
    xyz = [float(v) for v in element.get("xyz", "0 0 0").split()]
    rpy = [float(v) for v in element.get("rpy", "0 0 0").split()]
    return xyz, rpy


def _yaw_rotate(vec: list[float], yaw: float) -> list[float]:
    """Rotate a vector around z."""
    cos, sin = math.cos(yaw), math.sin(yaw)
    return [cos * vec[0] - sin * vec[1], sin * vec[0] + cos * vec[1], vec[2]]


def _wheel_contact_y(robot: ET.Element, side: str) -> float:
    """Return the y position, in the base frame, of the wheel contact axis.

    Composes the motor joint origin, the wheel joint origin and the origin of the
    wheel collision cylinder. Only yaw rotations are used by the motor joints.
    """
    motor_joint = robot.find(f"joint[@name='{NAMESPACE}/motor_{side}_joint']")
    wheel_joint = robot.find(f"joint[@name='{NAMESPACE}/motor_{side}_wheel_joint']")
    wheel_link = robot.find(f"link[@name='{NAMESPACE}/motor_{side}_wheel_link']")
    assert motor_joint is not None
    assert wheel_joint is not None
    assert wheel_link is not None
    motor_xyz, motor_rpy = _xyz_rpy(motor_joint.find("origin"))
    wheel_xyz, _ = _xyz_rpy(wheel_joint.find("origin"))
    collision_xyz, _ = _xyz_rpy(wheel_link.find("collision/origin"))
    local = [a + b for a, b in zip(wheel_xyz, collision_xyz, strict=True)]
    rotated = _yaw_rotate(local, motor_rpy[2])
    return motor_xyz[1] + rotated[1]


@pytest.fixture(params=MODES)
def robot(request: pytest.FixtureRequest) -> ET.Element:
    """Parsed robot for each mode."""
    return _robot(request.param)


@pytest.fixture(scope="module")
def differential() -> ET.Element:
    """Parsed robot in differential mode."""
    return _robot("differential")


def test_links_prefixed(robot: ET.Element) -> None:
    names = [link.get("name") for link in robot.findall("link")]
    assert names
    assert all(name.startswith(f"{NAMESPACE}/") for name in names)


def test_lidar_joint_fixed(robot: ET.Element) -> None:
    joint = robot.find("joint[@name='lidar_joint']")
    assert joint is not None
    assert joint.get("type") == "fixed"
    assert joint.find("limit") is None
    assert joint.find("axis") is None


def test_lidar_matches_firmware(robot: ET.Element) -> None:
    sensor = robot.find(".//sensor[@type='gpu_lidar']")
    assert sensor is not None
    assert int(sensor.findtext("lidar/scan/horizontal/samples")) == 132
    assert float(sensor.findtext("lidar/range/min")) == pytest.approx(0.02)
    assert float(sensor.findtext("lidar/range/max")) == pytest.approx(12.0)
    assert float(sensor.findtext("update_rate")) == pytest.approx(10)
    noise = sensor.find("lidar/noise")
    assert noise is not None
    assert noise.findtext("type") == "gaussian"
    assert float(noise.findtext("stddev")) == pytest.approx(0.01)


def test_lidar_frame_id(robot: ET.Element) -> None:
    sensor = robot.find(".//sensor[@type='gpu_lidar']")
    assert sensor is not None
    assert sensor.findtext("gz_frame_id") == f"{NAMESPACE}/lidar_link"
    assert sensor.findtext("topic") == f"{NAMESPACE}/scan"


def test_diff_drive_matches_firmware(differential: ET.Element) -> None:
    plugin = differential.find(".//plugin[@name='gz::sim::systems::DiffDrive']")
    assert plugin is not None
    assert float(plugin.findtext("wheel_separation")) == pytest.approx(WHEEL_SEPARATION)
    assert float(plugin.findtext("wheel_radius")) == pytest.approx(WHEEL_RADIUS)
    distance = abs(
        _wheel_contact_y(differential, "left") - _wheel_contact_y(differential, "right")
    )
    assert distance == pytest.approx(WHEEL_SEPARATION, abs=1e-3)
    for side in ("left", "right"):
        radius = differential.find(
            f"link[@name='{NAMESPACE}/motor_{side}_wheel_link']/collision/geometry/cylinder"
        )
        assert radius is not None
        assert float(radius.get("radius")) == pytest.approx(WHEEL_RADIUS)


@pytest.fixture(scope="module")
def holonomic() -> ET.Element:
    """Parsed robot in holonomic mode."""
    return _robot("holonomic")


def test_holonomic_has_no_roller_joints(holonomic: ET.Element) -> None:
    joints = holonomic.findall("joint")
    assert not [j.get("name") for j in joints if "roller" in j.get("name")]
    links = holonomic.findall("link")
    assert not [link.get("name") for link in links if "roller" in link.get("name")]
    continuous = [j.get("name") for j in joints if j.get("type") == "continuous"]
    assert sorted(continuous) == sorted(
        f"{NAMESPACE}/motor_{m}_wheel_joint" for m in ("left", "right", "middle")
    )


def test_holonomic_keeps_roller_visuals(holonomic: ET.Element) -> None:
    for motor in ("left", "right", "middle"):
        link = holonomic.find(f"link[@name='{NAMESPACE}/motor_{motor}_wheel_link']")
        assert link is not None
        visuals = link.findall("visual")
        assert len(visuals) == 1 + 9
        meshes = [v.find("geometry/mesh").get("filename") for v in visuals]
        assert sum(m.endswith("roller.stl") for m in meshes) == 9


def test_holonomic_wheel_collision(holonomic: ET.Element) -> None:
    for motor in ("left", "right", "middle"):
        link = holonomic.find(f"link[@name='{NAMESPACE}/motor_{motor}_wheel_link']")
        assert link is not None
        collisions = link.findall("collision")
        assert len(collisions) == 1
        cylinder = collisions[0].find("geometry/cylinder")
        assert cylinder is not None
        assert float(cylinder.get("radius")) == pytest.approx(WHEEL_RADIUS)
